#!/usr/bin/env bash\n# Prueba estructural: cada capacidad de las capturas (nicho construcción)\n# debe existir en código con implementación no-stub.\nset -euo pipefail\nROOT="$(cd "$(dirname "$0")/.." && pwd)"\nFAIL=0\npass() { echo "  ✅ $1"; }\nfail() { echo "  ❌ $1"; FAIL=$((FAIL+1)); }\n\ncheck_file() {\n  local f="$1" msg="$2"\n  if [[ -f "$ROOT/$f" ]]; then pass "$msg → $f"; else fail "$msg → FALTA $f"; fi\n}\ncheck_grep() {\n  local pattern="$1" path="$2" msg="$3"\n  if grep -Rql --include='*.java' --include='*.sql' --include='*.bpmn' --include='*.dmn' --include='*.html' --include='*.js' "$pattern" "$ROOT/$path" 2>/dev/null; then\n    pass "$msg"\n  else\n    fail "$msg (no match: $pattern in $path)"\n  fi\n}\n\necho "=============================================="\necho "PRUEBA DE COBERTURA — Nicho construcción"\necho "=============================================="\n\necho ""\necho "1) Cumplimiento de subcontratistas (certificados, vencimientos, recordatorios)"\ncheck_file "src/main/java/com/tuempresa/compliance/service/ComplianceService.java" "ComplianceService"\ncheck_file "src/main/java/com/tuempresa/compliance/job/ComplianceExpirationSweepJob.java" "Sweep vencimientos 30d/7d/vencido"\ncheck_grep "expiry_alert_level" "src" "Alertas de nivel de vencimiento"\ncheck_grep "notification_outbox" "src/main" "Cola de notificaciones de renovación"\ncheck_file "src/main/java/com/tuempresa/billing/delegate/ThreeWayMatchDelegate.java" "Three-way match (no pagar a ciegas)"\ncheck_file "src/test/java/com/tuempresa/billing/VersionFencingTest.java" "Version fencing test"\n\necho ""\necho "2) Documentación de proyecto (RFI, CO, submittals, daily reports)"\ncheck_file "src/main/java/com/tuempresa/documents/service/ProjectDocumentsService.java" "RFI + Change Orders"\ncheck_file "src/main/java/com/tuempresa/documents/service/SubmittalService.java" "Submittals"\ncheck_file "src/main/java/com/tuempresa/documents/service/DailyReportService.java" "Informes diarios"\ncheck_grep "rfi_routing_policy" "src/main/resources/db" "Enrutamiento RFI determinista en BD"\ncheck_file "src/main/resources/bpmn/rfiProcess.bpmn" "BPMN RFI"\n\necho ""\necho "3) Pagos / compensación / seguridad"\ncheck_file "src/main/java/com/tuempresa/billing/service/PaymentApplicationService.java" "Payment application"\ncheck_file "src/main/java/com/tuempresa/compensation/service/CompensationService.java" "Compensación + recovery_account"\ncheck_file "src/main/java/com/tuempresa/safety/job/OshaDeadlineSweepJob.java" "OSHA deadlines"\ncheck_file "src/main/resources/bpmn/paymentApprovalProcess.bpmn" "BPMN aprobación pago"\n\necho ""\necho "4) Identity por obra"\ncheck_file "src/main/java/com/tuempresa/identity/security/AuthFilter.java" "AuthFilter"\ncheck_grep "SAFETY_LEAD" "src/main" "Rol SAFETY_LEAD"\ncheck_grep "PROJECT_ENGINEER" "src/main" "Rol PROJECT_ENGINEER"\ncheck_grep "FINANCE" "src/main" "Rol FINANCE"\ncheck_file "src/main/resources/db/migration/V16__identity_templates_integration.sql" "Migración identity"\n\necho ""\necho "5) Front operativo"\ncheck_file "src/main/resources/static/index.html" "Shell front"\ncheck_file "src/main/resources/static/js/ops-app.js" "App JS colas"\ncheck_file "src/main/resources/static/js/api.js" "Cliente API"\ncheck_grep "/api/ops" "src/main/resources/static" "Front consume /api/ops"\n\necho ""\necho "6) Integración Procore (puente, no rewrite)"\ncheck_file "src/main/java/com/tuempresa/integration/procore/ProcoreClient.java" "Cliente HTTP Procore"\ncheck_file "src/main/java/com/tuempresa/integration/procore/ProcoreBridgeService.java" "Bridge"\ncheck_grep "DRY-RUN\|DRY_RUN\|dryRun\|isEnabled" "src/main/java/com/tuempresa/integration" "DRY-RUN explícito"\n\necho ""\necho "7) Plantillas documentales"\ncheck_file "src/main/java/com/tuempresa/templates/DocumentTemplateService.java" "Assembler"\ncheck_grep "Variable de plantilla requerida ausente" "src/main/java" "Fail-loud variables"\n\necho ""\necho "8) Anti-stub / anti-silencio"\nif grep -Rql "NotImplementedException\|TODO implement\|pass\s*$" "$ROOT/src/main/java" 2>/dev/null; then\n  fail "Hay stubs NotImplemented en main"\nelse\n  pass "Sin NotImplementedException en main"\nfi\ncheck_file "src/main/java/com/tuempresa/platform/web/ApiExceptionHandler.java" "Errores estructurados"\n\necho ""\necho "9) Inventario"\necho "  Java:     $(find "$ROOT/src" -name '*.java' | wc -l)"\necho "  SQL:      $(find "$ROOT" -name '*.sql' | wc -l)"\necho "  BPMN/DMN: $(find "$ROOT" -name '*.bpmn' -o -name '*.dmn' | wc -l)"\necho "  Tests:    $(find "$ROOT/src/test" -name '*.java' | wc -l)"\necho "  Static:   $(find "$ROOT/src/main/resources/static" -type f | wc -l)"\n\necho ""\nif [[ $FAIL -eq 0 ]]; then\n  echo "RESULTADO: TODAS LAS PRUEBAS ESTRUCTURALES OK"\n  exit 0\nelse\n  echo "RESULTADO: $FAIL fallos"\n  exit 1\nfi